import{i as e,r as t,s as n,t as r}from"./app-D1trhGny.js";var i=JSON.parse(`{"path":"/web3/smart/cardano/","title":"Cardano(ADA)","lang":"zh-CN","frontmatter":{"description":"Cardano(ADA) Cardano 是一个第三代区块链平台，旨在提供更安全、可扩展和可持续的去中心化应用。Cardano 由 IOHK（Input Output Hong Kong）开发，并以科学和学术研究为基础进行设计和实施。 2015 年 项目启动：2015 年，Cardano 项目由 Charles Hoskinson（以太坊联合创始人之一...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Cardano(ADA)\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/smart/cardano/"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"Cardano(ADA)"}],["meta",{"property":"og:description","content":"Cardano(ADA) Cardano 是一个第三代区块链平台，旨在提供更安全、可扩展和可持续的去中心化应用。Cardano 由 IOHK（Input Output Hong Kong）开发，并以科学和学术研究为基础进行设计和实施。 2015 年 项目启动：2015 年，Cardano 项目由 Charles Hoskinson（以太坊联合创始人之一..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.9,"words":571},"filePathRelative":"web3/smart/cardano/README.md","autoDesc":true}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="cardano-ada" tabindex="-1"><a class="header-anchor" href="#cardano-ada"><span>Cardano(ADA)</span></a></h1><p><a href="https://cardano.org/" target="_blank" rel="noopener noreferrer">Cardano</a> 是一个第三代区块链平台，旨在提供更安全、可扩展和可持续的去中心化应用。Cardano 由 IOHK（Input Output Hong Kong）开发，并以科学和学术研究为基础进行设计和实施。</p><h2 id="_2015-年" tabindex="-1"><a class="header-anchor" href="#_2015-年"><span>2015 年</span></a></h2><ul><li><strong>项目启动</strong>：2015 年，Cardano 项目由 Charles Hoskinson（以太坊联合创始人之一）和 Jeremy Wood 共同创立，目的是创建一个更加平衡和可持续的区块链生态系统。</li></ul><h2 id="_2017-年" tabindex="-1"><a class="header-anchor" href="#_2017-年"><span>2017 年</span></a></h2><ul><li><strong>主网发布</strong>：2017 年 9 月，Cardano 主网正式上线，推出了其第一个代币 ADA。Cardano 的第一个阶段被称为 Byron，重点是建立安全和稳定的区块链基础设施。</li><li><strong>去中心化目标</strong>：Cardano 从一开始就致力于通过分阶段的发展路线图实现完全去中心化。</li></ul><h2 id="_2018-年" tabindex="-1"><a class="header-anchor" href="#_2018-年"><span>2018 年</span></a></h2><ul><li><strong>Shelley 阶段</strong>：Cardano 进入 Shelley 阶段，专注于实现网络的去中心化。通过实施权益证明（PoS）共识机制，更多的节点参与网络，共同维护区块链的安全。</li></ul><h2 id="_2020-年" tabindex="-1"><a class="header-anchor" href="#_2020-年"><span>2020 年</span></a></h2><ul><li><strong>Shelley 主网升级</strong>：2020 年 7 月，Cardano 完成了 Shelley 主网升级，使网络更去中心化。持有 ADA 的用户可以参与质押，成为网络的一部分，并获得奖励。</li><li><strong>Goguen 阶段</strong>：Cardano 开始进入 Goguen 阶段，重点是引入智能合约功能，使开发者能够在 Cardano 平台上构建和部署去中心化应用（DApp）。</li></ul><h2 id="_2021-年" tabindex="-1"><a class="header-anchor" href="#_2021-年"><span>2021 年</span></a></h2><ul><li><strong>Mary 升级</strong>：2021 年 3 月，Cardano 实施了 Mary 升级，允许在 Cardano 上创建和交易原生代币。这一升级使 Cardano 成为一个多资产区块链。</li><li><strong>Alonzo 升级</strong>：2021 年 9 月，Cardano 完成了 Alonzo 升级，正式启用智能合约功能，支持 DeFi 和其他复杂的去中心化应用的开发。</li><li><strong>生态系统扩展</strong>：随着智能合约功能的启用，Cardano 生态系统迅速扩展，吸引了众多开发者和项目加入。</li></ul><h2 id="_2022-年" tabindex="-1"><a class="header-anchor" href="#_2022-年"><span>2022 年</span></a></h2><ul><li><strong>Basho 阶段</strong>：Cardano 进入 Basho 阶段，重点是优化网络性能和可扩展性。通过实施侧链和其他扩展解决方案，进一步提升 Cardano 的处理能力。</li><li><strong>生态系统发展</strong>：Cardano 持续吸引各种项目，包括 DeFi、NFT 和供应链管理等领域的应用。</li></ul>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};